Authenticate
==========
To connect to the Statistics Center websocket you will first have to get a JWT token from the login path described at [Login](#operations-Login-post_auth_login).
You can then use this token in the "Authorization" header to connect to the server.

You can then subscribe to certain topics to recieve the needed data:

```
websocket.send(JSON.stringify({
    subscription: 1,
    type: 'matches',
    identifier: '2019_2020',
}));
```

Types that can be subscribed:
- matches
- stats
- events
- live_events

You will then recieve a message event from the websocket containing the data for your subscription.

```javascript
websocket.on('message', (data) => { // do anything with given data });
```

Please see our full example of a node script of how this can be used.

Examples
==========

Node
-------------
```javascript
// using node version 10.16.0

const socketIO = require('socket.io-client');
const request = require('request');

// fill out following fields:
const apiUrl = '<API_URL>'; // i.e. https://hbl.kinexon.com/statistics-center/interfaces-api
const username = '<USERNAME>';
const password = '<PASSWORD>';

class Connector {
    async startWebsocketConnection() {
        const jwt = await this.loginAndExtractJwt(apiUrl, username, password);

        const websocket = socketIO.connect(
            this.getWebsocketAddress(apiUrl),
            {
                transportOptions: {
                    polling: {
                        extraHeaders: {
                            'Authorization': `Bearer ${jwt}`
                        }
                    }
                }
            }
        );

        websocket.on('message', this.handleWebSocketMessage);
        websocket.on('error', this.handleWebSocketError);


        // ============================================
        // Subscribe to any of the following identifiers
        // ============================================

        // send this request to receive a list of all matches
        websocket.send(JSON.stringify({
            subscription: 1,
            type: 'matches',
            identifier: '2019_2020',
        }));

        // send this request to receive a list of all stats in a <MATCH_ID>
        websocket.send(JSON.stringify({
            subscription: 1,
            type: 'stats',
            identifier: '<MATCH_ID>'
        }));

        // send this request to receive a list of all events in a <MATCH_ID>. Use the filter to receive only a certain
        // type
        websocket.send(JSON.stringify({
            subscription: 1,
            type: 'events',
            identifier: '<MATCH_ID>',
            filter: {
                event: 'shot'
            }
        }));

        // subscribe to this topic to get notifications for any live events that are happening on the field
        websocket.send(JSON.stringify({
            subscription: 1,
            type: 'live_events',
            identifier: '<MATCH_ID>'
        }));

    }

    handleWebSocketMessage(data) {
        if (data === 'Connected') {
            console.log('You are connected and authenticated.');

            // todo: add any scripts you need on connection here

            return;
        }

        data = JSON.parse(data);

        switch (data.type) {
            case 'stats':
                console.log('stats', data);
                // todo: handle any kind of data from type stats
                break;

            case 'events':
                console.log('events', data);
                // todo: handle any kind of data from type events
                break;

            case 'matches':
                console.log('matches', data);
                // todo: handle any kind of data from type matches
                break;

            case 'live_events':
                console.log('live_events', data);
                // todo: handle any kind of data from type live_events
                break;

            default:
                console.log('other', data);
                // todo: handle any other messages that come from the server
                break;
        }
    }

    handleWebSocketError(error) {
        console.warn(error);
        // todo: handle any error messages here
    }

    async loginAndExtractJwt(server, username, password) {
        const responseBody = await new Promise((resolve, reject) => {
            request({
                uri: `${server}/auth/login`,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: {
                    name: username,
                    password: password
                },
                json: true
            }, (error, response, body) => {
                if (error || response.statusCode === 401) {
                    const message = error || body;

                    console.warn('Error while logging in: \n', message);
                    reject(error);
                } else {
                    resolve(body);
                }
            })
        });

        return responseBody.jwt;
    }

    getWebsocketAddress(apiUrl) {
        const regex = /(http|https):\/\/([^:\/]+)/;
        const matches = regex.exec(apiUrl);
        const server = matches[2];

        return `ws://${server}:5002`;
    }
}

const myConnector = new Connector();
myConnector.startWebsocketConnection();
```

